class Solution:
    def removeDuplicateLetters(self, s: str) -> str:
        last={c:i for i,c in enumerate(s)}
        stack=[]; seen=set()
        for i,c in enumerate(s):
            if c in seen: continue
            while stack and stack[-1]>c and last[stack[-1]]>i:
                seen.remove(stack.pop())
            stack.append(c);seen.add(c)
        return ''.join(stack)

class Solution {
    public String removeDuplicateLetters(String s) {
        int[] last=new int[26];
        for(int i=0;i<s.length();i++) last[s.charAt(i)-'a']=i;
        boolean[] seen=new boolean[26];
        StringBuilder st=new StringBuilder();
        for(int i=0;i<s.length();i++){
            char c=s.charAt(i);int x=c-'a';if(seen[x])continue;
            while(st.length()>0){int y=st.charAt(st.length()-1)-'a';
                if(st.charAt(st.length()-1)<=c||last[y]<=i)break;
                seen[y]=false;st.deleteCharAt(st.length()-1);
            }
            st.append(c);seen[x]=true;
        }return st.toString();
    }
}

class Solution:
    def maxProduct(self, words: list[str]) -> int:
        masks=[]
        for word in words:
            mask=0
            for c in word: mask |= 1 << (ord(c)-ord('a'))
            masks.append(mask)
        best=0
        for i in range(len(words)):
            for j in range(i):
                if masks[i] & masks[j] == 0:
                    best=max(best,len(words[i])*len(words[j]))
        return best

class Solution {
    public int maxProduct(String[] words) {
        int n=words.length;int[] masks=new int[n];
        for(int i=0;i<n;i++)for(char c:words[i].toCharArray())masks[i]|=1<<(c-'a');
        int best=0;
        for(int i=0;i<n;i++)for(int j=0;j<i;j++)if((masks[i]&masks[j])==0)best=Math.max(best,words[i].length()*words[j].length());
