from functools import lru_cache
class Solution:
    def longestIncreasingPath(self, matrix: list[list[int]]) -> int:
        if not matrix or not matrix[0]: return 0
        m,n=len(matrix),len(matrix[0])
        @lru_cache(None)
        def dfs(r,c):
            best=1
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                nr,nc=r+dr,c+dc
                if 0<=nr<m and 0<=nc<n and matrix[nr][nc]>matrix[r][c]:
                    best=max(best,1+dfs(nr,nc))
            return best
        return max(dfs(r,c) for r in range(m) for c in range(n))

class Solution {
    private int[][] a,memo; private int m,n; private final int[][] dirs={{1,0},{-1,0},{0,1},{0,-1}};
    public int longestIncreasingPath(int[][] matrix) {
        if(matrix.length==0||matrix[0].length==0)return 0;
        a=matrix;m=a.length;n=a[0].length;memo=new int[m][n];int ans=0;
        for(int r=0;r<m;r++)for(int c=0;c<n;c++)ans=Math.max(ans,dfs(r,c));return ans;
    }
    private int dfs(int r,int c){if(memo[r][c]!=0)return memo[r][c];int best=1;
        for(int[] d:dirs){int x=r+d[0],y=c+d[1];if(x>=0&&x<m&&y>=0&&y<n&&a[x][y]>a[r][c])best=Math.max(best,1+dfs(x,y));}
        return memo[r][c]=best;
    }
}

