class Solution:
    def rob(self, root) -> int:
        def dfs(node):
            if not node: return (0,0)
            lt,ls=dfs(node.left);rt,rs=dfs(node.right)
            take=node.val+ls+rs
            skip=max(lt,ls)+max(rt,rs)
