class Solution:
    def largestDivisibleSubset(self, nums: list[int]) -> list[int]:
        if not nums:return []
        nums.sort();n=len(nums);dp=[1]*n;prev=[-1]*n
        best=0
        for i in range(n):
            for j in range(i):
                if nums[i]%nums[j]==0 and dp[j]+1>dp[i]:
                    dp[i]=dp[j]+1;prev[i]=j
            if dp[i]>dp[best]:best=i
        out=[]
        while best!=-1:out.append(nums[best]);best=prev[best]
        return out[::-1]

import java.util.*;
class Solution {
    public List<Integer> largestDivisibleSubset(int[] nums) {
        List<Integer> out=new ArrayList<>();if(nums.length==0)return out;Arrays.sort(nums);int n=nums.length;
        int[]dp=new int[n],prev=new int[n];Arrays.fill(dp,1);Arrays.fill(prev,-1);int best=0;
        for(int i=0;i<n;i++){for(int j=0;j<i;j++)if(nums[i]%nums[j]==0&&dp[j]+1>dp[i]){dp[i]=dp[j]+1;prev[i]=j;}if(dp[i]>dp[best])best=i;}
        while(best!=-1){out.add(nums[best]);best=prev[best];}Collections.reverse(out);return out;
    }
}

