class Solution:
    def kthSmallest(self, matrix: list[list[int]], k: int) -> int:
        n=len(matrix);lo,hi=matrix[0][0],matrix[-1][-1]
        while lo<hi:
            mid=(lo+hi)//2;r=n-1;c=0;count=0
            while r>=0 and c<n:
                if matrix[r][c]<=mid:count+=r+1;c+=1
                else:r-=1
            if count<k:lo=mid+1
            else:hi=mid
        return lo

class Solution {
    public int kthSmallest(int[][] matrix,int k) {
        int n=matrix.length,lo=matrix[0][0],hi=matrix[n-1][n-1];
        while(lo<hi){int mid=lo+(hi-lo)/2,count=0,r=n-1,c=0;
            while(r>=0&&c<n){if(matrix[r][c]<=mid){count+=r+1;c++;}else r--;}
            if(count<k)lo=mid+1;else hi=mid;
        }return lo;
    }
}

