        lines=input.split('\n');lengths=[0]*(len(lines)+1);best=0
        for line in lines:
            depth=line.count('\t');name=line[depth:]
            if '.' in name:best=max(best,lengths[depth]+len(name))
            else:lengths[depth+1]=lengths[depth]+len(name)+1
        return best

