from collections import Counter
class Solution:
    def longestSubstring(self, s: str, k: int) -> int:
        if len(s)<k:return 0
        counts=Counter(s)
        for c,n in counts.items():
            if n<k:
                return max((self.longestSubstring(part,k) for part in s.split(c)),default=0)
        return len(s)

class Solution {
    public int longestSubstring(String s,int k) {
        if(s.length()<k)return 0;int[]cnt=new int[26];for(char c:s.toCharArray())cnt[c-'a']++;
        for(int i=0;i<s.length();i++)if(cnt[s.charAt(i)-'a']<k){int j=i+1;while(j<s.length()&&cnt[s.charAt(j)-'a']<k)j++;return Math.max(longestSubstring(s.substring(0,i),k),longestSubstring(s.substring(j),k));}
        return s.length();
    }
}

class Solution:
    def maxRotateFunction(self, nums: list[int]) -> int:
        n=len(nums)
        if not n:return 0
        total=sum(nums);f=sum(i*x for i,x in enumerate(nums));best=f
        for k in range(1,n):
            f=f+total-n*nums[n-k];best=max(best,f)
        return best

class Solution {
    public int maxRotateFunction(int[] nums) {
        int n=nums.length;if(n==0)return 0;long total=0,f=0;
        for(int i=0;i<n;i++){total+=nums[i];f+=(long)i*nums[i];}long best=f;
        for(int k=1;k<n;k++){f=f+total-(long)n*nums[n-k];best=Math.max(best,f);}return (int)best;
    }
}

